#include <iostream>
#include <string>
using namespace std;

string check(int guess, int target) {
    if (guess < target) {
        return "太小啦喵";
    } else if (guess > target) {
        return "太大啦喵";
    } else {
        return "猜中啦喵";
    }
}

int play(int target, int picks[], int n) {
    int i = 0;
    while (i < n) {
        int guess = picks[i];
        i = i + 1;

        cout << "本喵报 " << guess << "：" << check(guess, target) << endl;

        if (guess == target) {
            return i;
        }
    }
    return 0;
}

int main() {
    int target = {target};
    int picks[4] = {10, 42, 68, 90};

